import React, { useState } from 'react';
import './CSS/AdminDashboard.css';

const AdminDashboard = () => {
  const [activeTab, setActiveTab] = useState('overview');

  // Sample data states
  const [users, setUsers] = useState([
    { id: '#101', name: 'Anisha', email: 'anisha@seller.com', role: 'Seller', status: 'Active' },
    { id: '#102', name: 'Mona', email: 'mona@gmail.com', role: 'User', status: 'Active' },
    { id: '#103', name: 'Jhanvi', email: 'jhanvi@gmail.com', role: 'User', status: 'Active' },
    { id: '#104', name: 'Bharath', email: 'bharath@seller.com', role: 'Seller', status: 'Blocked' },
  ]);

  const toggleStatus = (id) => {
    setUsers(users.map(u => u.id === id ? { ...u, status: u.status === 'Active' ? 'Blocked' : 'Active' } : u));
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'overview':
        return (
          <div className="tab-panel">
            <h2>System Overview</h2>
            <div className="stats-cards">
              <div className="card"><h3>Total Users</h3><p>{users.filter(u => u.role === 'User').length}</p></div>
              <div className="card"><h3>Total Sellers</h3><p>{users.filter(u => u.role === 'Seller').length}</p></div>
              <div className="card"><h3>Active Accounts</h3><p>{users.filter(u => u.status === 'Active').length}</p></div>
              <div className="card"><h3>Blocked Accounts</h3><p>{users.filter(u => u.status === 'Blocked').length}</p></div>
            </div>
          </div>
        );

      case 'users':
        return (
          <div className="tab-panel">
            <h2>User Management & Activity</h2>
            <table className="admin-table">
              <thead>
                <tr>
                  <th>ID</th><th>Name</th><th>Email</th><th>Status</th><th>Action</th>
                </tr>
              </thead>
              <tbody>
                {users.filter(u => u.role === 'User').map(user => (
                  <tr key={user.id}>
                    <td>{user.id}</td>
                    <td>{user.name}</td>
                    <td>{user.email}</td>
                    <td><span className={`badge ${user.status.toLowerCase()}`}>{user.status}</span></td>
                    <td>
                      <button 
                        className={`action-btn ${user.status === 'Active' ? 'block' : 'grant'}`}
                        onClick={() => toggleStatus(user.id)}
                      >
                        {user.status === 'Active' ? 'Block Access' : 'Grant Access'}
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        );

      case 'sellers':
        return (
          <div className="tab-panel">
            <h2>Seller Management & Verification</h2>
            <table className="admin-table">
              <thead>
                <tr>
                  <th>ID</th><th>Store Name</th><th>Email</th><th>Status</th><th>Action</th>
                </tr>
              </thead>
              <tbody>
                {users.filter(u => u.role === 'Seller').map(seller => (
                  <tr key={seller.id}>
                    <td>{seller.id}</td>
                    <td>{seller.name}</td>
                    <td>{seller.email}</td>
                    <td><span className={`badge ${seller.status.toLowerCase()}`}>{seller.status}</span></td>
                    <td>
                      <button 
                        className={`action-btn ${seller.status === 'Active' ? 'block' : 'grant'}`}
                        onClick={() => toggleStatus(seller.id)}
                      >
                        {seller.status === 'Active' ? 'Block Store' : 'Approve Store'}
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        );

      case 'logs':
        return (
          <div className="tab-panel">
            <h2>Activity Audit Logs</h2>
            <ul className="log-list">
              <li><strong>[User]</strong> Mona (#102) logged in successfully.</li>
              <li><strong>[Seller]</strong> Bharath (#104) account status changed to Blocked.</li>
              <li><strong>[Admin]</strong> System security audit completed.</li>
            </ul>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="admin-layout">
      {/* Sidebar Navigation */}
      <aside className="admin-sidebar">
        <h3 className="sidebar-title">Admin Panel</h3>
        <nav className="sidebar-menu">
          <button className={activeTab === 'overview' ? 'active' : ''} onClick={() => setActiveTab('overview')}>
            📊 Overview
          </button>
          <button className={activeTab === 'users' ? 'active' : ''} onClick={() => setActiveTab('users')}>
            👤 User Activity
          </button>
          <button className={activeTab === 'sellers' ? 'active' : ''} onClick={() => setActiveTab('sellers')}>
            🏪 Seller Activity
          </button>
          <button className={activeTab === 'logs' ? 'active' : ''} onClick={() => setActiveTab('logs')}>
            📜 Audit Logs
          </button>
        </nav>
      </aside>

      {/* Main Content Area */}
      <main className="admin-content">
        {renderContent()}
      </main>
    </div>
  );
};

export default AdminDashboard;
